function getlinkSvg(t){
    const {java} = this;    
    let svg = `
  <svg width="32" height="32" xmlns="http://www.w3.org/2000/svg">
    <text x="16" y="27" font-family="Roboto Condensed" text-anchor="middle" dominant-baseline="middle" font-size="25" font-weight="bold" fill="#555">
    ${t}
    </text>
  </svg>`;

    return "data:image/svg+xml;base64," + java.base64Encode(svg);
}

function getImage(t,link){	   
	   return `<img src="data:svg;base64,,{"js":"getlinkSvg('${t}')","click":"openUrl('${link}')"}">`
}	

function openUrl(u){
	const {java} = this;
	u = "https://"+u.replace(/https?:\/\//g,'');
	let openUrl = "legado://import/addToBookshelf?src="+u+","+`{"origin":"https://xn--pxtr7m.com"}`
	  java.openUrl(openUrl);
}	


